770		name = strings.TrimSpace(name)
771		if strings.ContainsAny(name, "/\\\x00") || filepath.IsAbs(name) {
772			return nil, errors.New("invalid task group name")
773		}
774		if strings.ContainsAny(name, `:*?"<>|`) || strings.HasSuffix(name, ".") {
775			return nil, errors.New("invalid task group name")
776		}
777		name = util.SafeFilename(name)
778		if name == "" || name == "." || name == ".." {
779			return nil, errors.New("invalid task group name")
780		}
781		d.lock.Lock()
782		defer d.lock.Unlock()
783		requested := filepath.Join(parentPath, name)
784		var dir string
785		for suffix := 0; suffix <= maxTaskGroupDirSuffix; suffix++ {
786			candidate := requested
787			if suffix > 0 {
788				candidate = fmt.Sprintf("%s (%d)", requested, suffix)
789			}
790			if !d.isDownloadPathAllowed(candidate) {
791				return nil, errors.New("task group directory is outside the white list")
