	for suffix := 0; suffix <= maxTaskGroupDirSuffix; suffix++ {
		candidate := requested
		if suffix > 0 {
			candidate = fmt.Sprintf("%s (%d)", requested, suffix)
		}
		if !d.isDownloadPathAllowed(candidate) {
			return nil, errors.New("task group directory is outside the white list")
		}
