39		if opts == nil {
40			opts = &base.Options{}
41		}
42		cfg, err := d.GetConfig()
43		if err != nil {
44			return "", err
45		}
46		base := dartTrimSpace(opts.Path)
47		if base == "" {
48			base = cfg.DownloadDir
49		}
50		// Refuse to fall through to the process working directory when neither the
51		// task nor the config names a directory.
52		if base == "" {
53			return "", errors.New("download directory is empty")
54		}
55		if group != nil && opts.SkipAutoCategorize {
56			return d.initDownloadPathForTask(base, group)
57		}
58		target := base
59		if !opts.SkipAutoCategorize {
60			if category := categoryForResource(cfg, res); category != nil {
61				target = dartTrimSpace(category.Path)
62			}
63		}
64		dir, err := d.initDownloadPath(target)
65		if err != nil && target != base {
66			d.Logger.Warn().Err(err).Msgf("category directory %q rejected by white list, falling back to %q", target, base)
67			dir, err = d.initDownloadPath(base)
68		}
69		if err != nil {
70			return "", err
71		}
72		return dir, nil
73	}
